from pathlib import Path

path = Path('/home/ubuntu/crest-automotive-astro/src/layouts/SiteLayout.astro')
text = path.read_text()

# Crest Luxe typography and the midnight / slate / silver / electric-blue palette.
text = text.replace('<meta name="theme-color" content="#071528" />', '<meta name="theme-color" content="#131315" />')
text = text.replace("<link href=\"https://fonts.googleapis.com/css2?family=DM+Serif+Display:ital@0;1&family=Poppins:wght@400;500;600;700;800&display=swap\" rel=\"stylesheet\" />", "<link href=\"https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap\" rel=\"stylesheet\" />")
text = text.replace("font-family: 'Poppins', sans-serif", "font-family: 'Inter', sans-serif")
text = text.replace("--ink: #071528; --ink-2: #0b2038; --panel: #102743; --gold: #e2b968; --gold-soft: #f2d18a; --white: #fffdf7; --muted: var(--white); --line: rgba(222,181,92,.22); --max: 1240px;", "--ink: #131315; --ink-2: #0f172a; --panel: #1b1b1d; --gold: #3b82f6; --gold-soft: #bec6e0; --white: #e4e2e4; --muted: #c6c6cd; --line: rgba(198,198,205,.16); --max: 1440px;")
text = text.replace("--ink:#071528; --ink-2:#0b2038; --panel:#102743; --gold:#e2b968; --gold-soft:#f2d18a; --white:#fffdf7; --muted:#fffdf7; --line:rgba(222,181,92,.22); --max:1240px;", "--ink:#131315; --ink-2:#0f172a; --panel:#1b1b1d; --gold:#3b82f6; --gold-soft:#bec6e0; --white:#e4e2e4; --muted:#c6c6cd; --line:rgba(198,198,205,.16); --max:1440px;")

# Repoint the shared visual primitives to the specified design language.
text = text.replace("background: var(--ink); font-family: 'Inter', sans-serif;", "background: var(--ink); font-family: 'Inter', sans-serif; letter-spacing: 0; ")
text = text.replace("background: radial-gradient(circle, rgba(226,185,104,.16), transparent 68%);", "background: radial-gradient(circle, rgba(59,130,246,.12), transparent 68%);")
text = text.replace("background: rgba(7,21,40,.92);", "background: rgba(19,19,21,.94);")
text = text.replace("backdrop-filter: blur(20px);", "backdrop-filter: blur(20px);")
text = text.replace("border-radius: 999px; font-size: 10px;", "border-radius: .375rem; font-size: 10px;")
text = text.replace("background: linear-gradient(135deg, #e2b968, #f2d18a);", "background: #3b82f6;")
text = text.replace("box-shadow: inset 0 1px rgba(255,255,255,.45);", "box-shadow: inset 0 1px rgba(255,255,255,.22);")
text = text.replace(".button-gold:hover { background: var(--gold-soft); box-shadow: 0 14px 32px rgba(226,185,104,.18); }", ".button-gold:hover { background: #60a5fa; box-shadow: 0 12px 28px rgba(59,130,246,.22); }")
text = text.replace("border-color: #718198;", "border-color: #909097;")
text = text.replace("background: linear-gradient(135deg, rgba(226,185,104,.06), rgba(11,32,56,.72));", "background: rgba(255,255,255,.04);")
text = text.replace("background: rgba(226,185,104,.10);", "background: rgba(255,255,255,.10);")
text = text.replace("background: linear-gradient(150deg, #0b2038, #071528);", "background: linear-gradient(150deg, #1b1b1d, #0e0e10);")
text = text.replace("background: linear-gradient(150deg, var(--navy-2), var(--navy));", "background: linear-gradient(150deg, #1b1b1d, #0e0e10);")

# Add a final token-driven layer for page-local cards and controls. This is deliberately global
# because the existing pages are independently authored Astro documents with shared class names.
layer = '''\n<style is="global">\n  :root { --surface:#131315; --surface-lowest:#0e0e10; --surface-low:#1b1b1d; --surface-container:#1f1f21; --surface-high:#2a2a2b; --surface-highest:#353436; --silver:#c6c6cd; --outline:#909097; --outline-variant:#45464d; --electric:#3b82f6; --electric-bright:#60a5fa; }\n  body { background:var(--surface); color:#e4e2e4; }\n  h1,h2,h3,h4,h5,h6 { font-family:'Inter',sans-serif; font-weight:600; }\n  main h1,main h2,main h3 { letter-spacing:-.035em; }\n  main h1 em,main h2 em,main h3 em { font-family:'Inter',sans-serif; color:var(--silver); font-style:normal; }\n  .site-header { background:rgba(19,19,21,.78); }\n  .site-header.is-scrolled { background:rgba(19,19,21,.94); border-color:rgba(198,198,205,.18); }\n  .brand-mark { border-radius:.25rem; color:var(--electric); border-color:var(--electric); transform:none; }\n  .phone-dot { background:var(--electric); box-shadow:0 0 0 4px rgba(59,130,246,.14); }\n  .button,.header-call,.menu-toggle { border-radius:.375rem; }\n  .button-gold { color:#fff; background:var(--electric); }\n  .button-gold:hover { color:#fff; background:var(--electric-bright); }\n  .button-ghost { border-color:var(--outline); background:rgba(255,255,255,.04); }\n  .button-ghost:hover { border-color:var(--electric); background:rgba(255,255,255,.10); }\n  main p,main li { color:#c6c6cd !important; }\n  main .eyebrow { color:var(--electric) !important; }\n  main a:not(.button) { color:#bec6e0; }\n  main a:not(.button):hover { color:#fff; }\n  main input,main select,main textarea { border-radius:.25rem !important; border-color:rgba(198,198,205,.28) !important; background:#1e293b !important; color:#e4e2e4 !important; }\n  main input:focus,main select:focus,main textarea:focus { border-color:var(--electric) !important; box-shadow:0 0 0 3px rgba(59,130,246,.16) !important; }\n  main .service-row,main .package-card,main .coating-card,main .addon-card,main .choice-card,main .image-card,main .hero-image,main .page-hero-image,main .package-hero-card,main .why-image,main .faq-visual,main .contact-card,main .map-wrap,main .calculator-summary,main .calculator-form { border-radius:.5rem; border-color:rgba(198,198,205,.16); background-color:rgba(255,255,255,.045); backdrop-filter:blur(20px); }\n  main .service-row:hover,main .package-card:hover,main .coating-card:hover,main .addon-card:hover,main .choice-card:hover { border-color:rgba(59,130,246,.72); background-color:rgba(59,130,246,.08); }\n  main .service-row,main .package-card,main .coating-card,main .addon-card,main .choice-card { box-shadow:inset 1px 1px rgba(255,255,255,.08); }\n  main th { background:#1f1f21 !important; }\n  main td { background:#1b1b1d; border-color:rgba(198,198,205,.12) !important; }\n  main th:first-child,main td:first-child { background:#1f1f21 !important; }\n  .site-footer { background:linear-gradient(150deg,#1b1b1d,#0e0e10); }\n  .footer-links a,.footer-bottom,.footer-main>p { color:#c6c6cd !important; }\n  .mobile-menu { background:rgba(14,14,16,.98) !important; }\n  @media (max-width:620px) { main h1 { font-size:32px !important; line-height:1.2; } main h2 { font-size:32px !important; line-height:1.2; } }\n</style>\n'''
text = text.replace('</html>\n<style>', '</html>\n' + layer + '<style>', 1)
path.write_text(text)
